import java.util.*;

public class Main {
    Node copyRandomList(Node head) {
        if (head == null) return null;
        Map<Node, Node> mapping = new HashMap<>();                                 // maps each original node to its brand new copy
        Node node = head;
        while (node != null) {
            mapping.put(node, new Node(node.val));                                    // first pass: create every copy node (values only)
            node = node.next;
        }
        node = head;
        while (node != null) {
            mapping.get(node).next = mapping.get(node.next);                          // second pass: wire up next and random using the map
            mapping.get(node).random = mapping.get(node.random);
            node = node.next;
        }
        return mapping.get(head);
    }

    public static void main(String[] args) {
        Main solution = new Main();
        Node n1 = new Node(7), n2 = new Node(13), n3 = new Node(11);
        n1.next = n2; n2.next = n3;
        n2.random = n1;
        Node result = solution.copyRandomList(n1);
        StringBuilder sb = new StringBuilder();
        while (result != null) { sb.append(result.val).append(" "); result = result.next; }
        System.out.println(sb.toString().trim());
    }
}

