Node* copyRandomList(Node* head) {
    if (!head) return nullptr;
    unordered_map<Node*, Node*> mapping;                                          // maps each original node to its brand new copy
    for (Node* node = head; node; node = node->next) {
        mapping[node] = new Node(node->val);                                          // first pass: create every copy node (values only)
    }
    for (Node* node = head; node; node = node->next) {
        mapping[node]->next = mapping[node->next];                                     // second pass: wire up next and random using the map
        mapping[node]->random = mapping[node->random];
    }
    return mapping[head];
}

