import java.util.*;

public class Main {
    Node copyRandomList(Node head) {
        if (head == null) return null;

        Node node = head;                                                            // phase 1: weave a copy right after each original node
        while (node != null) {
            Node copy = new Node(node.val);
            copy.next = node.next;
            node.next = copy;
            node = copy.next;
        }

        node = head;                                                                 // phase 2: assign random pointers using the weaved structure
        while (node != null) {
            if (node.random != null) {
                node.next.random = node.random.next;                                      // the copy right after node.random IS node.random's copy
            }
            node = node.next.next;
        }

        node = head;                                                                 // phase 3: unweave into two separate lists
        Node copyHead = head.next;
        while (node != null) {
            Node copy = node.next;
            node.next = copy.next;
            copy.next = (copy.next != null) ? copy.next.next : null;
            node = node.next;
        }
        return copyHead;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        Node n1 = new Node(7), n2 = new Node(13), n3 = new Node(11);
        n1.next = n2; n2.next = n3;
        n2.random = n1;
        Node result = solution.copyRandomList(n1);
        StringBuilder sb = new StringBuilder();
        while (result != null) { sb.append(result.val).append(" "); result = result.next; }
        System.out.println(sb.toString().trim());
    }
}

